def dataset():
    passages = [{"id": key, "title": title, "text": text} for key, title, text, _ in NOTES]
    passages += [{"id": key, "title": key.replace("_", " "), "text": text} for key, text in DISTRACTORS]
    queries = [{"question": question, "relevant": [key], "category": "direct" if i == 0 else "paraphrase"}
               for key, _, _, questions in NOTES for i, question in enumerate(questions)]
    queries += [
        {"question": "Contrast learning from target labels with finding groups without labels.", "relevant": ["supervised", "unsupervised"], "category": "comparison"},
        {"question": "Compare keyword-based search with embedding-based search.", "relevant": ["bm25", "dense"], "category": "comparison"},
        {"question": "How do spreading sessions over time and recalling without notes differ?", "relevant": ["spacing", "recall"], "category": "comparison"},
        {"question": "Compare a single recursively split predictor to an ensemble of randomized trees.", "relevant": ["trees", "forest"], "category": "comparison"},
        {"question": "How does nearest-neighbor prediction differ from centroid clustering?", "relevant": ["knn", "kmeans"], "category": "comparison"},
        {"question": "What is the difference between combining ranked lists and jointly scoring a query with a passage?", "relevant": ["fusion", "reranking"], "category": "comparison"},
    ]
    return passages, queries
